#if PROFILES_IMPLEMENTED
 static void NonBlocking(LaunchConfigurationProfiles profiles,string data){using(var ready=new ManualResetEvent(false))using(var release=new ManualResetEvent(false)){Exception failed=null;var thread=new Thread(()=>{try{using(var versionMutex=new Mutex(false,"Local\\OrangeVersionLibrary-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(data.ToUpperInvariant()))))using(var snapshotMutex=new Mutex(false,"Local\\OrangeSaveEnvironments-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(data.ToUpperInvariant())).ToLowerInvariant())){versionMutex.WaitOne();snapshotMutex.WaitOne();ready.Set();release.WaitOne();snapshotMutex.ReleaseMutex();versionMutex.ReleaseMutex();}}catch(Exception error){failed=error;ready.Set();}});thread.Start();ready.WaitOne();try{if(failed!=null)throw failed;var watch=Stopwatch.StartNew();Check(profiles.List().Length>0&&profiles.Select("launcher").Id=="launcher"&&watch.ElapsedMilliseconds<2000,"browse and selection do not wait for global version or snapshot mutation locks");}finally{release.Set();thread.Join();}}}
 static void Game(string game){Put(Path.Combine(game,"ProjectZomboid64.exe"),"isolated executable fixture");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-javaagent:foreign.jar\",\"-Xmx12g\",\"-XX:+AlwaysPreTouch\"]}");Put(Path.Combine(game,"version.txt"),"42.21.0");}
 static void Snapshot(LaunchConfigurationProfiles profiles,string root,string game,string user,string data){string config=Path.Combine(game,"ProjectZomboid64.json");byte[] originalConfig=File.ReadAllBytes(config);File.WriteAllText(config,"{\"vmArgs\":[]}");var engine=new Engine(game,user,data,true,null,n=>new Process[0]);var snapshots=new SaveEnvironments(engine);var plan=snapshots.Preview("Sandbox/Original");Check(plan.ready,"snapshot fixture ready: "+string.Join(";",plan.warnings));var record=snapshots.Create("Sandbox/Original",Path.Combine(root,"独立快照"),"独立快照",plan.stamp,CancellationToken.None,null,r=>Put(Path.Combine(r.RuntimeHome,"prepared"),"runtime fixture"));File.WriteAllBytes(config,originalConfig);byte[] manifest=File.ReadAllBytes(record.ManifestPath);Directory.Move(game,game+"-gone");try{var item=profiles.List().Single(x=>x.Id=="snapshot:"+record.Id);Check(item.Kind=="frozen"&&item.Available&&item.Snapshot.GamePath==record.GamePath,"registered snapshot lists after source disappears");var selected=profiles.Select(item.Id);Check(selected.Context==null&&selected.Snapshot.ModIds.SequenceEqual(record.ModIds)&&selected.Snapshot.ModRoots.Length==record.ModRoots.Length,"frozen resolution exposes pinned record only");Check(new LaunchConfigurationProfiles(data,game,user).SelectedId==item.Id,"snapshot selection persists");Check(manifest.SequenceEqual(File.ReadAllBytes(record.ManifestPath)),"snapshot selection leaves manifest exact");File.WriteAllText(record.ManifestPath,"corrupt fixture manifest");var damaged=profiles.List().Single(x=>x.Id==item.Id);Check(!damaged.Available&&damaged.ErrorCode=="invalid-snapshot"&&profiles.Select("launcher").Id=="launcher","one invalid snapshot cannot block unrelated configuration browsing or selection");File.WriteAllBytes(record.ManifestPath,manifest);}finally{Directory.Move(game+"-gone",game);}}
